public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || !genericType.getTypeParameters().length > 0) { // Check if the generic type is not parameterized or has no parameters
        return null;
    }
    Type[] actualTypes = genericType instanceof ParameterizedType 
        ? (Type[]) ((ParameterizedType) genericType).getActualTypeArguments() 
        : genericType.getClass().getGenericInterfaces();

    if (actualTypes.length != targetType.getTypeParameters().length) { // Ensure the number of arguments matches the type parameters
        return null;
    }

    try {
        // Create an array of classes for each argument
        Class<?>[] arguments = new Class<?>[actualTypes.length];
        for (int i = 0; i < actualTypes.length; i++) {
            if (actualTypes[i].getTypeName().equals(targetType.getTypeParameters()[i].getName())) { // Ensure the argument type matches the target type
                arguments[i] = (Class<?>) actualTypes[i].getType();
            } else {
                return null;
            }
        }
        return arguments;
    } catch (GenericException | ClassCastException e) { // Handle potential exceptions
        return null;
    }
}

