public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("DayStep must be positive");
    }

    // Convert to Julia but keep the explanation
    int year = timeBucket / (1000 * 365 * 24);
    int month = (timeBucket / (1000 * 365) - year * 1000) / 30;
    int day = (timeBucket - year * 1000 * 365) - month * 30 * 24;

    int dayInBucket = day / dayStep;

    int newYear = year;
    int newMonth = month;
    int newDay = day - dayInBucket * dayStep;

    if (newDay < 0) {
        newDay += 24 * 30 * 12;
        newMonth--;
    }
    if (newMonth < 0) {
        newMonth += 12;
        newYear--;
    }

    if (newMonth == 0 && newDay == 0) {
        newMonth = 12;
        newYear--;
    }

    return (newYear * 1000 * 365 + newMonth * 30 * 24 + newDay) * dayStep;
}

public static int computeUTF8Size(CharSequence str, int index, int len) {
    if (str == null) {
        throw new IllegalArgumentException("The input sequence cannot be null.");
    }
    if (str.length() <= index || index < 0) {
        throw new IndexOutOfBoundsException("Invalid index provided.");
    }
    if (index + len > str.length()) {
        throw new IndexOutOfBoundsException("Slice length exceeds the string length.");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if ((c & 0xC0) == 0x80) {
            size += 1; // Continuation byte
        } else if ((c & 0xE0) == 0xC0 || (c & 0xF0) == 0xE0) {
            size += 2; // Two-byte character
        } else if ((c & 0xF8) == 0xF0) {
            size += 3; // Three-byte character
        } else {
            size += 4; // Four-byte character
        }
    }

    return size;
}

