public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    boolean inEscape = false;

    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (inEscape) {
            inEscape = false;
            if (c == 'n') {
                result.append('\n');
            } else if (c == 't') {
                result.append('\t');
            } else if (c == 'r') {
                result.append('\r');
            } else {
                result.append(c);
            }
        } else {
            if (c == '\\') {
                inEscape = true;
            } else {
                result.append(c);
            }
        }
    }

    return result.toString();
}

