public short readShort(final int offset) {
    // Check if the offset is within a valid range
    if (offset < -Integer.MAX_VALUE || offset + Short.BYTES > this.limit) {
        throw new IllegalArgumentException("Invalid offset: " + offset + ". Limit is " + this.limit);
    }

    // Read the short value at the given offset
    byte sign = this.b[offset];
    byte high = this.b[offset + 1];
    byte low = this.b[offset + 2];

    short value = (short) (high << 8 | low);

    // Apply the sign to the value
    return (short) ((sign & 0x80) == 0 ? value : -(value + 1));
}

