public ByteVector putInt(final int intValue) {
    int offset = (intValue >> 24);
    byte msb = (byte) offset;

    offset = ((intValue >> 16) & 0xff);
    byte mbs = (byte) offset;

    offset = ((intValue >> 8) & 0xff);
    byte lsb = (byte) offset;

    byte[] bytes = { msb, mbs, lsb };
    this.bytes = Arrays.copyOf(this.bytes, this.bytes.length + 3);
    System.arraycopy(bytes, 0, this.bytes, this.bytes.length - bytes.length, bytes.length);

    return this;
}

