private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (graph == null || vertices == null || graph.isEmpty() || vertices.isEmpty()) {
        throw new IllegalArgumentException("Graph and vertices cannot be null or empty.");
    }

    if (vertices.size() < 2) {
        return true; // A clique with less than 2 vertices is trivially a clique.
    }

    V firstVertex = vertices.iterator().next();

    for (V vertex : vertices) {
        if (!graph.isVertexConnected(firstVertex, vertex)) {
            return false; // If any vertex is not connected to the first vertex, the subgraph is not a clique.
        }
    }

    return true; // All vertices are connected to each other, so the subgraph is a clique.
}

