public List<Integer> computeUpperBounds(List<K> keys) {
    List<Integer> upperBounds = new ArrayList<>();
    Map<K, Integer> upperBoundMap = new HashMap<>();

    // Ensure the input list is not null or empty
    if (keys == null || keys.isEmpty()) {
        throw new IllegalArgumentException("Input list cannot be null or empty");
    }

    // Calculate the upper bounds for each key
    int maxs = Integer.MIN_VALUE;
    for (K key : keys) {
        int currMax = maxs;
        for (K currKey : keys) {
            currMax = Math.max(currMax, currKey.getValue());
        }
        upperBoundMap.put(key, currMax);
        maxs = currMax;
        upperBounds.add(currMax);
    }

    return upperBounds;
}

