public static String[] toNoNullStringArray(Object[] array) {
    String[] filteredArray = new String[array.length];
    int count = 0;
    for (Object obj : array) {
        if (obj != null && obj instanceof String) {
            filteredArray[count++] = (String) obj;
        }
    }
    // Ensure the new array size matches the count of non-null elements
    if (count != array.length) {
        String[] result = new String[count];
        System.arraycopy(filteredArray, 0, result, 0, count);
        return result;
    }
    return filteredArray;
}

