public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    BufferedReader reader = new BufferedReader(new FileReader(file));

    // Assuming the file format is: timestamp, profile, duration
    String line;
    long start = -1;
    long end = -1;

    while ((line = reader.readLine()) != null) {
        String[] parts = line.split(",");
        long timestamp = Long.parseLong(parts[0]);
        String profile = parts[1];
        long duration = Long.parseLong(parts[2]);

        if(start == -1) {
            start = timestamp;
            end = timestamp + duration;
        } else {
            // Check if the current profile falls within the time range
            if(timestamp >= start && timestamp <= end) {
                threadSnapshots.add(new ThreadSnapshot(profile, timestamp));
            }

            // Update the start and end of the current time range if necessary
            if(timestamp + duration > end) {
                end = timestamp + duration;
            }
        }
    }

    reader.close();
    return threadSnapshots;
}
